const ENTITIES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (ch) => ENTITIES[ch]);

function html(strings, ...values) {
  let out = strings[0];
  values.forEach((value, i) => (out += escapeHtml(value) + strings[i + 1]));
  return out;
}

const review = { author: "Kemi", text: "good <u>rice</u>" };
console.log(html`<li><b>${review.author}</b>: ${review.text}</li>`);

